def load_review():
    import sys
    import types

    if hashlib.sha256(REVIEW_SOURCE.encode()).hexdigest() != REVIEW_SHA256:
        raise ValueError("RECOVERY_REVIEW_SOURCE_CHANGED")
    module = types.ModuleType("_pinned_clock_recovery_review")
    sys.modules[module.__name__] = module
    exec(compile(REVIEW_SOURCE, "<pinned_recovery_review>", "exec"), module.__dict__)
    return module


def bootstrap():
    if not all(
        Path(n).is_file() and hashlib.sha256(Path(n).read_bytes()).hexdigest() == h
        for n, h in CORE_PINS.items()
    ):
        print(
            json.dumps(
                {
                    "runtime_clock_recovery": "BLOCKED_KEEP_PAUSED",
                    "stop_reason": "INSTALLED_SOURCE_HASH_MISMATCH",
                    "order_writes": 0,
                    "orders_enabled": False,
                    "execution_approved": False,
                    "live_trading_enabled": False,
                }
            )
        )
        raise SystemExit(2) from None


if __name__ == "__main__":
    bootstrap()

