def report(status, store, *, changed=False, **extra):
    ledger = r.setup_context(store, allow_stale_period=True)
    day, week = r.period_keys(store.now(), ledger.policy.week_start_kst)
    return {
        "runtime_clock_recovery": status,
        "shared_clock_changed": changed,
        "financial_database_changed": False,
        "checkpoint_appended": changed,
        "period_keys_match": (day, week) == (ledger.daily_key, ledger.weekly_key),
        "periods": {
            "stored_day_kst": ledger.daily_key,
            "current_day_kst": day,
            "stored_week_kst": ledger.weekly_key,
            "current_week_kst": week,
        },
        "period_baselines_changed": False,
        "execution_approved": False,
        "orders_enabled": False,
        "live_trading_enabled": False,
        "order_writes": 0,
        "http_attempts": 0,
        "credentials_accessed": False,
        "paused": True,
        "risk_state": "NORMAL",
        "startup_hold_seconds": STARTUP_HOLD,
        "next_action": "KEEP_PAUSED_REVIEW_PERIODS_NO_ORDER_RETRY",
    } | extra


def context(store, anchor, parent, clocks):
    ledger = r.setup_context(store, allow_stale_period=True)
    root = r._setup_root(parent)
    record = r._read_setup(ledger)
    r.require(record.get("stage") == "PREPARED", "RECOVERY_SETUP_NOT_COMPLETE")
    r.require(
        str(anchor.installation_id()) == record.get("anchor_installation"), "SETUP_ANCHOR_CHANGED"
    )
    storage = r._storage_objects(anchor, root, record, clocks)
    r.require(
        record.get("expected_runtime_binding") == runtime_storage_binding(storage),
        "SETUP_INTENT_INVALID",
    )
    r._verify_done(ledger, record)
    order = DurableOrderQuota(
        root / "order-quota",
        r.ACCOUNT,
        UUID(record["order_journal"]),
        read_only=True,
        monotonic=clocks.monotonic,
        wall_clock=clocks.wall_clock,
    )
    try:
        validate_journal_bindings(ledger, order)
        r.require(not order.flow_records() and not order._events(), "RECOVERY_ORDER_JOURNAL_USED")
    finally:
        order.close()
    return ledger, root, record, storage


@contextmanager
def locked_raw_shared(storage, anchor, *, write):
    obj = object.__new__(SharedWeightJournal)
    obj.directory, obj.scope = storage.shared_directory, storage.shared_scope
    obj._paths()
    db_id, lock_id = obj._identity(obj.path), obj._identity(obj.lock_path)
    r.require(obj.path.stat().st_size <= 16 * 1024 * 1024, "SHARED_STORAGE_SIZE_LIMIT")
    with anchor.scope(obj.scope, storage.shared_identity, read_only=not write) as checkpoint:
        assert isinstance(checkpoint, CheckpointContext)
        fd = os.open(obj.lock_path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
        c = None
        try:
            r.require((os.fstat(fd).st_dev, os.fstat(fd).st_ino) == lock_id, "SHARED_FILE_REPLACED")
            try:
                fcntl.flock(fd, (fcntl.LOCK_EX if write else fcntl.LOCK_SH) | fcntl.LOCK_NB)
            except BlockingIOError:
                raise r.Blocked("SHARED_WRITER_BUSY") from None
            r.require(
                obj._identity(obj.path) == db_id and obj._identity(obj.lock_path) == lock_id,
                "SHARED_FILE_REPLACED",
            )
            r.require(
                not any(
                    Path(str(obj.path) + suffix).exists() for suffix in ("-wal", "-shm", "-journal")
                ),
                "RECOVERY_SQLITE_SIDECAR_PRESENT",
            )
            c = sqlite3.connect(
                obj.path.resolve().as_uri() + ("?mode=rw" if write else "?mode=ro"),
                uri=True,
                isolation_level=None,
                timeout=2,
            )
            c.row_factory = sqlite3.Row
            c.execute("PRAGMA synchronous=FULL" if write else "PRAGMA query_only=ON")
            c.execute("BEGIN IMMEDIATE" if write else "BEGIN")
            r.require(fingerprint(c) == checkpoint.digest, "SHARED_CHECKPOINT_MISMATCH")
            rows = c.execute("SELECT * FROM meta").fetchall()
            r.require(len(rows) == 1, "SHARED_STORAGE_INVALID")
            meta = dict(rows[0])
            r.require(
                (meta["identity"], meta["scope"], meta["policy"])
                == (str(storage.shared_identity), obj.scope, POLICY),
                "SHARED_STORAGE_BINDING_MISMATCH",
            )
            r.require(
                type(meta["total"]) is int
                and meta["total"] == 0
                and c.execute("SELECT COUNT(*) FROM attempts").fetchone()[0] == 0,
                "RECOVERY_SHARED_JOURNAL_USED",
            )
            r.require(
                type(meta["stopped"]) is int and meta["stopped"] == 0,
                "RECOVERY_STOPPED_JOURNAL_REQUIRES_REVIEW",
            )
            r.require(
                all(
                    type(meta[k]) in (float, int) and math.isfinite(meta[k])
                    for k in ("start", "wall", "last")
                )
                and meta["last"] >= meta["start"],
                "SHARED_STORAGE_INVALID",
            )
            yield c, meta, checkpoint, obj.path
            if c.in_transaction:
                c.execute("COMMIT")
        except Exception:
            if c is not None and c.in_transaction:
                c.execute("ROLLBACK")
            raise
        finally:
            if c is not None:
                c.close()
            os.close(fd)


def current_clocks(clocks):
    mono, wall, boot = clocks.monotonic(), clocks.wall_clock(), clocks.boot()
    r.require(
        type(mono) in (float, int)
        and math.isfinite(mono)
        and mono >= 0
        and isinstance(wall, datetime)
        and wall.tzinfo is not None
        and wall.utcoffset() == UTC.utcoffset(wall)
        and str(UUID(boot)) == boot,
        "RECOVERY_CURRENT_CLOCK_INVALID",
    )
    return mono, wall.timestamp(), boot


def clock_valid(meta, current):
    mono, wall, boot = current
    return (
        boot == meta["boot"]
        and mono >= meta["last"]
        and abs((wall - meta["wall"]) - (mono - meta["start"])) <= 1
    )


def write_new(path, content):
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
    try:
        with os.fdopen(fd, "wb", closefd=False) as stream:
            stream.write(content)
            stream.flush()
            os.fsync(fd)
    finally:
        os.close(fd)


def fsync_directory(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def recover(store, anchor, *, parent=r.STORAGE_PARENT, clocks=None, after_sqlite_commit=None):
    clocks = clocks or RuntimeClocks()
    financial_before = r.readonly_token(store.engine)
    changed = False
    # The account row lock fences cooperating account writers without changing the lease or ledger.
    with store.engine.connect() as financial, financial.begin():
        financial.execute(text("SET LOCAL lock_timeout='2s'"))
        financial.execute(text("SET LOCAL statement_timeout='5s'"))
        financial.execute(
            select(r.accounts.c.account_id)
            .where(r.accounts.c.account_id == r.ACCOUNT)
            .with_for_update()
        ).one()
        ledger, root, record, storage = context(store, anchor, parent, clocks)
        with locked_raw_shared(storage, anchor, write=True) as (c, meta, checkpoint, path):
            current = current_clocks(clocks)
            if not clock_valid(meta, current):
                recovery_id = uuid5(
                    storage.shared_identity,
                    "unused-clock-recovery:" + str(checkpoint.revision) + ":" + checkpoint.digest,
                )
                audit = root / ("clock-recovery-" + str(recovery_id))
                r.require(
                    not audit.exists() and not audit.is_symlink(),
                    "RECOVERY_PRIOR_INTENT_REQUIRES_REVIEW",
                )
                backup = path.read_bytes()
                before_files = r.readonly_files(root)
                new_meta = meta | {
                    "boot": current[2],
                    "start": current[0],
                    "wall": current[1],
                    "last": current[0],
                }
                # No rows, charges, stop flags, identities, policies or bindings are reset.
                intent = {
                    "version": 1,
                    "action": "RECOVER_UNUSED_SHARED_CLOCK_V1",
                    "source_reference": r.SOURCE_REFERENCE,
                    "account": r.ACCOUNT,
                    "scope": storage.shared_scope,
                    "journal": str(storage.shared_identity),
                    "before_revision": checkpoint.revision,
                    "before_fingerprint": checkpoint.digest,
                    "original_sqlite_sha256": hashlib.sha256(backup).hexdigest(),
                    "preserved_ledger_sha256": r.setup_preserved(ledger),
                    "before_meta": meta,
                    "proposed_meta": new_meta,
                    "execution_approved": False,
                }
                intent_bytes = (json.dumps(intent, sort_keys=True) + "\n").encode()
                r.require(
                    len(before_files) + 2 <= 16
                    and sum((root / name).stat().st_size for name in before_files)
                    + len(backup)
                    + len(intent_bytes)
                    <= 32 * 1024 * 1024,
                    "RECOVERY_AUDIT_STORAGE_LIMIT",
                )
                os.mkdir(audit, mode=0o700)
                write_new(audit / "original.sqlite3", backup)
                write_new(audit / "intent.json", intent_bytes)
                fsync_directory(audit)
                fsync_directory(root)
                # Verify the preserved DB is an exact anchored snapshot before touching the active file.
                b = sqlite3.connect(
                    (audit / "original.sqlite3").as_uri() + "?mode=ro&immutable=1", uri=True
                )
                try:
                    r.require(
                        fingerprint(b) == checkpoint.digest, "RECOVERY_BACKUP_VERIFICATION_FAILED"
                    )
                finally:
                    b.close()
                r.require(
                    current_clocks(clocks)[2] == current[2], "RECOVERY_CLOCK_CHANGED_DURING_APPLY"
                )
                c.execute(
                    "UPDATE meta SET boot=?,start=?,wall=?,last=?",
                    (current[2], current[0], current[1], current[0]),
                )
                after = fingerprint(c)
                # SQLite must commit before PG. An interrupted cross-store commit stays blocked;
                # preserve its intent+backup and never guess a checkpoint or refund capacity.
                c.execute("COMMIT")
                if after_sqlite_commit is not None:
                    after_sqlite_commit()
                anchor.append(
                    checkpoint.connection,
                    storage.shared_scope,
                    storage.shared_identity,
                    checkpoint.revision + 1,
                    after,
                )
                changed = True
        r.require(
            r.readonly_token(store.engine) == financial_before, "RECOVERY_FINANCIAL_STATE_CHANGED"
        )
    result = status(store, anchor, parent=parent, clocks=clocks)
    result.update(
        shared_clock_changed=changed, checkpoint_appended=changed, recovery_audit_created=changed
    )
    return result


def status(store, anchor, *, parent=r.STORAGE_PARENT, clocks=None):
    clocks = clocks or RuntimeClocks()
    ledger, root, record, storage = context(store, anchor, parent, clocks)
    before = r.readonly_token(store.engine)
    files = r.readonly_files(root)
    with locked_raw_shared(storage, anchor, write=False) as (_, meta, _, _):
        current = current_clocks(clocks)
        r.require(clock_valid(meta, current), "SHARED_CLOCK_OR_BOOT_CHANGED")
        ready = current[0] - meta["start"] >= STARTUP_HOLD
    r.require(
        r.setup_preserved(ledger) == record["preserved_ledger_sha256"],
        "RECOVERY_FINANCIAL_STATE_CHANGED",
    )
    r.require(before == r.readonly_token(store.engine), "RECOVERY_FINANCIAL_STATE_CHANGED")
    r.require(files == r.readonly_files(root), "REVIEW_STORAGE_CHANGED_DURING_READ")
    return report(
        "RECOVERED_KEEP_PAUSED" if ready else "WAIT_STARTUP_HOLD",
        store,
        startup_ready=ready,
        storage_bindings_verified=True,
    )


def main():
    import argparse

    from sqlalchemy import create_engine

    from packages.persistence.demo_shared_checkpoint import SharedWeightAnchorStore

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--phase", choices=("recover", "status"), required=True)
    parser.add_argument("--apply-clock-recovery", action="store_true")
    args = parser.parse_args()
    engines = []
    stage = "CONTEXT_VALIDATION"
    code = 2
    result = {
        "runtime_clock_recovery": "BLOCKED_KEEP_PAUSED",
        "order_writes": 0,
        "http_attempts": 0,
        "execution_approved": False,
        "orders_enabled": False,
        "live_trading_enabled": False,
        "next_action": "REVIEW_FAILURE_NO_AUTOMATIC_RESET",
    }
    try:
        r.require(
            os.getenv("TRADING_MODE", "PAPER").upper() != "LIVE"
            and os.getenv("LIVE_TRADING_ENABLED", "false").lower() == "false",
            "REVIEW_LIVE_CONTEXT_FORBIDDEN",
        )
        r.require(
            args.apply_clock_recovery == (args.phase == "recover"),
            "RECOVERY_EXPLICIT_APPLY_REQUIRED",
        )
        stage = "SOURCE_VALIDATION"
        r.verify_install_files("post")
        for _ in range(2):
            engines.append(
                create_engine(
                    r.database_url().get_secret_value(), connect_args={"connect_timeout": 2}
                )
            )
        store, anchor = r.DemoStore(engines[0]), SharedWeightAnchorStore(engines[1])
        stage = "UNUSED_SHARED_CLOCK_RECOVERY" if args.phase == "recover" else "READ_ONLY_POSTCHECK"
        result = (recover if args.phase == "recover" else status)(store, anchor)
        code = 0
    except Exception as error:
        reason, category = r.safe_failure(error)
        if isinstance(error, r.Blocked) and str(error) in RECOVERY_CODES:
            reason, category = str(error), "CONTROL_REFUSAL"
        result.update(stage=stage, stop_reason=reason, failure_category=category)
    finally:
        for engine in reversed(engines):
            try:
                engine.dispose()
            except Exception:
                result = {
                    "runtime_clock_recovery": "BLOCKED_KEEP_PAUSED",
                    "stop_reason": "REVIEW_CLEANUP_FAILED",
                    "order_writes": 0,
                    "execution_approved": False,
                    "orders_enabled": False,
                    "live_trading_enabled": False,
                }
                code = 2
    print(json.dumps(result), flush=True)
    raise SystemExit(code)


RECOVERY_CODES = frozenset(
    {
        "RECOVERY_REVIEW_SOURCE_CHANGED",
        "RECOVERY_AUDIT_STORAGE_LIMIT",
        "RECOVERY_SETUP_NOT_COMPLETE",
        "RECOVERY_ORDER_JOURNAL_USED",
        "RECOVERY_SQLITE_SIDECAR_PRESENT",
        "RECOVERY_SHARED_JOURNAL_USED",
        "RECOVERY_STOPPED_JOURNAL_REQUIRES_REVIEW",
        "RECOVERY_CURRENT_CLOCK_INVALID",
        "RECOVERY_PRIOR_INTENT_REQUIRES_REVIEW",
        "RECOVERY_BACKUP_VERIFICATION_FAILED",
        "RECOVERY_CLOCK_CHANGED_DURING_APPLY",
        "RECOVERY_FINANCIAL_STATE_CHANGED",
        "RECOVERY_EXPLICIT_APPLY_REQUIRED",
    }
)

if __name__ == "__main__":
    main()
